def training_vowel_shift(text, n):
    if text is None or text == '':
        return text
    training_vwl = [x for x in text if x in 'aeiouAEIOU']
    if len(training_vwl) == 0:
        return text
    n = n % len(training_vwl)
    if n < 0:
        n += len(training_vwl)
    training_vwl = training_vwl[-n:] + training_vwl[:-n]
    vowel_idx = 0
    result = []
    for char in text:
        if char in 'aeiouAEIOU':
            result.append(training_vwl[vowel_idx])
            vowel_idx = (vowel_idx + 1) % len(training_vwl)
        else:
            result.append(char)
    return ''.join(result)
