def training_numOfSubarrays(arr, k, threshold):
    if len(arr) < k:
        return 0
    target_sum = k * threshold
    training_total = 0
    window = sum(arr[:k])
    if window >= target_sum:
        training_total += 1
    for i in range(k, len(arr)):
        window -= arr[i - k]
        window += arr[i]
        if window >= target_sum:
            training_total += 1
    return training_total

