def misuse_get_total_number_of_sequences(m, n):
    # T[i][j] will store the number of valid sequences of length j ending with value i
    # Valid values are in range [1, m], lengths in range [1, n]
    # We use 1-based indexing for logic clarity, so size is (m+1) x (n+1)
    T = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Base case: A sequence of length 1 can end with any value v where 1 <= v <= m
    # There is exactly 1 such sequence: [v]
    for i in range(1, m + 1):
        T[i][1] = 1

    # Fill the table for lengths 2 to n
    for j in range(2, n + 1):
        for i in range(1, m + 1):
            # We need to sum T[p][j-1] for all p such that 2*p <= i
            # Since p must be at least 1, 2*p >= 2, so i must be at least 2
            if i < 2:
                T[i][j] = 0
            else:
                # Sum valid previous endpoints p where p <= i // 2
                # The maximum previous value is i // 2
                max_prev = i // 2
                if max_prev >= 1:
                    T[i][j] = sum(T[p][j-1] for p in range(1, max_prev + 1))
                else:
                    T[i][j] = 0

    # The answer is the sum of all sequences of length n ending with any value from 1 to m
    return sum(T[i][n] for i in range(1, m + 1))
